import 'package:flutter/material.dart';
import 'package:madar_application/madar_application.dart';

import '../accounts/account_document.dart';
import '../reports/restaurant_report.dart';
import '../reports/reports_view_model.dart';
import '../reports/saved_report_pdf_viewer.dart';
import '../ui/components.dart';
import '../ui/dialogs.dart';
import '../ui/theme.dart';

/// Confirmation reads only the acknowledged saved sale. Report/native actions
/// cannot post or repeat the sale and retain generated bytes for handoff retry.
Future<String?> showSalePaidDialog(
  BuildContext context, {
  required AccountDocument account,
  required String saleId,
  bool canOpenDetails = false,
}) async {
  final report = RestaurantReportComposer(
    account,
    compareText: (_, _) => throw const FormatException('collation_unavailable'),
  ).sale(saleId);
  final delivery = ReportDeliveryController();
  bool busy = false;
  String? feedback;
  Future<void> deliver(
    String action,
    StateSetter set,
    BuildContext dialogContext,
  ) async {
    if (busy) return;
    set(() {
      busy = true;
      feedback = null;
    });
    try {
      if (delivery.bytes == null) {
        final generated = await delivery.generate(report);
        if (generated is! CapabilitySuccess<void>) {
          feedback = 'تعذّر إنشاء الوصل. أعد المحاولة.';
          return;
        }
      }
      if (!dialogContext.mounted) return;
      final result = switch (action) {
        'open' => await openSavedReportPdf(
          dialogContext,
          title: report.title,
          bytes: delivery.bytes!,
        ),
        'print' => await delivery.print(),
        'share' => await delivery.share(),
        _ => await delivery.save(),
      };
      feedback = switch (result) {
        CapabilitySuccess() =>
          action == 'print'
              ? 'تم إرسال الوصل للطباعة.'
              : action == 'open'
              ? 'تم فتح عرض PDF.'
              : action == 'share'
              ? 'تم تسليم PDF للنظام.'
              : 'تم حفظ PDF.',
        CapabilityCancelled() => 'أُلغي الطلب؛ البيع محفوظ ولم يتكرر.',
        CapabilityFailure() => 'تعذّر إرسال الوصل؛ أعد المحاولة بالنسخة نفسها.',
      };
    } on Object {
      feedback = 'تعذّر إرسال الوصل؛ البيع محفوظ.';
    } finally {
      busy = false;
      if (dialogContext.mounted) set(() {});
    }
  }

  final result = await showDakhlDialog<String>(
    context: context,
    title: 'تم تأكيد البيع النقدي',
    subtitle: report.reference,
    body: Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        const Icon(Icons.check_circle, color: DakhlTokens.green, size: 48),
        const DakhlBadge('مدفوع نقداً'),
        const Text('الفاتورة محفوظة، والمخزن محدّث.'),
        for (final section in report.sections) ...[
          if (section.title.isNotEmpty)
            Text(section.title, style: Theme.of(context).textTheme.titleMedium),
          for (final row in section.rows)
            Padding(
              padding: const EdgeInsets.symmetric(vertical: 6),
              child: Wrap(
                alignment: WrapAlignment.spaceBetween,
                spacing: 12,
                runSpacing: 4,
                children: [for (final value in row) Text(value)],
              ),
            ),
        ],
      ],
    ),
    actions: [
      StatefulBuilder(
        builder: (ctx, set) => Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            if (feedback != null) DakhlStatus(message: feedback!),
            Wrap(
              spacing: 8,
              runSpacing: 8,
              children: [
                DakhlButton(
                  label: 'طباعة الوصل',
                  busy: busy,
                  onPressed: busy ? null : () => deliver('print', set, ctx),
                ),
                DakhlButton(
                  label: 'فتح PDF',
                  onPressed: busy ? null : () => deliver('open', set, ctx),
                ),
                DakhlButton(
                  label: 'مشاركة PDF',
                  onPressed: busy ? null : () => deliver('share', set, ctx),
                ),
                DakhlButton(
                  label: 'حفظ PDF',
                  onPressed: busy ? null : () => deliver('save', set, ctx),
                ),
                DakhlButton(
                  label: 'تفاصيل الوصل',
                  onPressed: busy || !canOpenDetails
                      ? null
                      : () => Navigator.of(ctx).pop('details'),
                ),
                DakhlButton(
                  label: 'طلب جديد / إغلاق',
                  onPressed: busy ? null : () => Navigator.of(ctx).pop('close'),
                ),
              ],
            ),
          ],
        ),
      ),
    ],
    canDismiss: () async => !busy,
  );
  delivery.dispose();
  return result;
}
